<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Product; use App\Models\Category; use App\Models\Subcategory; use App\Models\ProductVariant; use App\Models\Banner; class DashboardController extends Controller { public function index() { $stats = ['total_products'=>Product::count(),'active_products'=>Product::where('status','active')->count(),'categories'=>Category::count(),'subcategories'=>Subcategory::count(),'in_stock'=>ProductVariant::where('availability','in_stock')->count(),'out_of_stock'=>ProductVariant::where('availability','out_of_stock')->count(),'featured'=>Product::where('is_featured',1)->count(),'trending'=>Product::where('is_trending',1)->count(),'new_arrivals'=>Product::where('is_new',1)->count(),'active_banners'=>Banner::where('is_active',1)->count()]; return view('admin.dashboard', compact('stats')); } }